Редактор создавал отдельный TripPlan. Он должен получить родительский объект через @ObservedObject; одинаковый id не объединяет два экземпляра.

import SwiftUI
import Observation
@Observable final class TripPlan {
    let id = 72
    var isPacked = false
}
struct TripScreen: View {
    @State private var plan = TripPlan()
    var body: some View {
        VStack {
            Text("Собрано: \(plan.isPacked)")
            PackingEditor(plan: plan)
        }
    }
}
struct PackingEditor: View {
    @Bindable var plan: TripPlan
    var body: some View {
        Toggle("Вещи собраны", isOn: $plan.isPacked)
    }
}

Toggle записывает Bool через $plan.isPacked в общий объект. Родитель читает то же свойство, поэтому его надпись отражает включение и выключение.

import SwiftUI
final class TripPlan: ObservableObject {
    let id = 72
    @Published var participants = 1
}
struct TripScreen: View {
    @StateObject private var plan = TripPlan()
    var body: some View {
        VStack {
            Text("Участники: \(plan.participants)")
            ParticipantsEditor(plan: plan)
        }
    }
}
struct ParticipantsEditor: View {
    @ObservedObject var plan: TripPlan
    var body: some View {
        Stepper("Участники: \(plan.participants)",
                value: $plan.participants, in: 1...4)
    }
}

@StateObject хранит один план, @ObservedObject передаёт его редактору. @Published сообщает об изменении числа; диапазон Stepper ограничивает его пользовательское управление.
